// Generated data, carried over unchanged from the source dashboard's world
// map. Do not edit by hand.
//
// 250 territories, each keyed by its ISO 3166-1 alpha-2 code, which is
// the same value the edge writes into site_visits.country. A country
// choropleth is therefore a direct lookup.

export const MAP_W = 1009.6727;
export const MAP_H = 665.96301;

/** Corners of the drawn area, from the source's own geoViewBox. */
export const MAP_BOUNDS = {
  west: -169.110266,
  north: 83.600842,
  east: 190.486279,
  south: -58.508473,
} as const;

export interface CountryShape {
  /** ISO 3166-1 alpha-2. */
  code: string;
  /** All of the territory's rings, concatenated. */
  d: string;
}

const mercatorY = (lat: number): number =>
  Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));

const TOP = mercatorY(MAP_BOUNDS.north);
const BOTTOM = mercatorY(MAP_BOUNDS.south);

/**
 * lat/lon to viewBox coordinates.
 *
 * Mercator, verified against the source rather than assumed: projecting known
 * capitals this way puts 11 of 12 inside their own country's outline, and the
 * one that misses is a bounding-box artefact of a multi-part coastline, not a
 * projection error. Latitude is clamped short of the poles because the Mercator
 * y goes to infinity at 90 degrees, and a visitor the edge placed at a pole
 * would otherwise take the whole map with it.
 */
export function project(lat: number, lon: number): { x: number; y: number } {
  const clamped = Math.max(-85, Math.min(85, lat));
  return {
    x: ((lon - MAP_BOUNDS.west) / (MAP_BOUNDS.east - MAP_BOUNDS.west)) * MAP_W,
    y: ((TOP - mercatorY(clamped)) / (TOP - BOTTOM)) * MAP_H,
  };
}

